"""Build the research report from retained calibration and replay records."""
import argparse
import json
from pathlib import Path
import numpy as np
import pandas as pd
from .full_readout_fit import HERE,NAMES

def summarize(run,plots):
 r=json.loads((run/'run.json').read_text());a=json.loads((run/'score_audit.json').read_text());rows=pd.read_csv(run/'expiry_scores.csv');x=np.array(r['selected_parameters']);old=np.array(r['baseline']);lo=np.array(r['bounds_lower']);hi=np.array(r['bounds_upper'])
 lines=['# Fixed-reservoir, eleven-parameter SPX/VIX calibration','', 'Completed 24 October 2026. Exploratory in-sample calibration, with separate numerical checking on the same market quotes.','', '## Scope and implementation','', 'The user confirmed eleven free parameters. OU grids/counts/rates, driver correlations, projection powers, Q risk prices and C0=1/Y0=F0=0 are fixed. Optional orthogonal/echo channels remain off. Beta_J is strictly positive. All 1294 OTM SPX cutoff-3 quotes at 29/57/119/211/302/666/1030 days, all 217 OTM VIX quotes at 27/55/118/153 days, and four VIX forwards enter the objective. Extremes remain excluded. No market holdout is introduced.','', 'Raw positive importance-weighted payoffs replace the historical strike-dependent control estimator for this run. The old zero-shift reference is repriced on the SAME new paths and quadrature as the new candidate. Its losses here must not be compared directly with historical controlled-estimator loss 308.64. No smoothing or clipping is applied. Some raw estimates are zero because the sampled paths have no positive payoff; their IVs are marked unavailable in the plots, while their prices and errors remain in the scores. These cases do not establish a true zero option price.','', 'The immutable cache stores reservoir projections and equity increments, not candidate G/M_Q. Every candidate recomputes G, its date-zero Q normalizer, stock values and conditional VIX. Stock updates remain at 512 steps per trading day on exact event dates. One common stock grid preserves dependence across SPX maturities.','', '## Parameters','', '| Parameter | Old reference | Selected | Search interval | Boundary flag |','|---|---:|---:|---|---|']
 for n,b,v,l,h in zip(NAMES,old,x,lo,hi):
  flag='Near lower bound' if (v-l)/(h-l)<.01 else ('Near upper bound' if (h-v)/(h-l)<.01 else '')
  lines.append(f'| {n} | {b:.10g} | {v:.10g} | [{l:g}, {h:g}] | {flag} |')
 lines+=['','Boundaries and finite optimization budget prevent interpreting this vector as a unique, globally identified calibration. The positive beta_J lower bound 0.01 is a declared numerical search choice. A boundary preference does not establish that a particular economic asymmetry is absent.','', '## Same-estimator comparisons','', '| Ensemble | Old reference loss | Selected loss | Change | Old / selected inside bid–ask |','|---|---:|---:|---:|---|']
 for role,label in [('search','Searching simulations, conditional GH12'),('check','Separate simulations, conditional GH24'),('check_gh12','Same checking states, conditional GH12')]:
  b=next(t for t in r['scores'] if t['role']==role and t['candidate']=='baseline');s=next(t for t in r['scores'] if t['role']==role and t['candidate']=='selected');lines.append(f"| {label} | {b['total']:.4f} | {s['total']:.4f} | {s['total']-b['total']:+.4f} | {b['inside_bidask']} / {s['inside_bidask']} |")
 b=next(t for t in r['scores'] if t['role']=='check' and t['candidate']=='baseline');s=next(t for t in r['scores'] if t['role']=='check' and t['candidate']=='selected')
 conclusion=('The selected candidate has a lower estimated loss on the separate checking ensemble, but the uncertainty diagnostics below do not establish a reliable improvement.' if s['total']<b['total'] else 'The searching improvement reverses on the separate checking ensemble; do not adopt this as a better fit.')
 lines+=['',conclusion+' These are numerical comparisons on the SAME in-sample market observations, not market out-of-sample results.','', '| Checking loss component | Old reference | Selected |','|---|---:|---:|']
 for name in ['SPX','VIX','forwards','curve_penalty','state_penalty']:lines.append(f"| {name} | {b['components'][name]:.6g} | {s['components'][name]:.6g} |")
 lines+=['', '## Every agreed maturity','', '| Instrument | Days | Quotes | Old interval MSE | Selected interval MSE | Selected inside bid–ask |','|---|---:|---:|---:|---:|---:|']
 c=rows[rows.role=='check']
 for (instrument,days),g in c.groupby(['instrument','expiry_days']):
  br=g[g.candidate=='baseline'].iloc[0];sr=g[g.candidate=='selected'].iloc[0];lines.append(f'| {instrument} | {days} | {sr.quotes} | {br.interval_MSE:.4f} | {sr.interval_MSE:.4f} | {sr.inside_bidask} |')
 f=pd.read_csv(run/'forwards_check_selected.csv');lines+=['','Selected VIX forward errors (points): '+', '.join(f'{v:+.4f}' for v in f.error_points)+'.','', '## Numerical checks and limits','', 'Six focused Python tests pass: production readout and Gaussian-expectation correspondence, all eleven stock derivatives against finite differences, and existing all-maturity membership/objective checks. Two end-to-end directional Jacobian checks passed before search. These checks do not certify pricing convergence. No new Lean theorem or compiler audit was requested or claimed; existing formal identities retain their prior conditional scope.','',f"Saved prices and SEs replay, all {a['source_count']} captured source/input hashes match, and {a['unique_seed_count']} recorded seeds are distinct across searching/checking streams. All six score records reproduce. Raw positive estimates have zero within-side strike monotonicity violations at every maturity. Replay does not independently regenerate the simulations.",'',f"The descriptive paired eight-block jackknife SE of the checking loss change is {a['paired_eight_block_jackknife_loss_change_SE']:.4f}. This SE is much larger than the estimated loss reduction, and one leave-one-block comparison reverses sign. The numerical improvement is not robustly established. Few blocks and rare-tail sampling limit interpretation; this is not a calibrated confidence certificate.",'',f"On matching checking states, selected GH24 versus GH12 price changes have median {a['GH24_vs_GH12_selected_median_price_scales']:.4g} and maximum {a['GH24_vs_GH12_selected_max_price_scales']:.4g} quote scales across all options (the median includes unchanged SPX prices); the VIX-only median is {a['GH24_vs_GH12_selected_VIX_median_price_scales']:.4g}. Search used GH12; check used GH24, with GH12 checking records retained to distinguish this change from outer sampling. Neither order proves convergence.",'', 'Normalizers use GH48 and interpolation on 257 transformed-time knots. Maximum independent same-GH-order interpolation probe errors: '+', '.join(f"{t['role']}/{t['candidate']}: {t['normalizer_probe_error']:.3g}" for t in r['scores'])+'. These are sampled interpolation checks, not a bound on GH bias. The selected candidate exceeds the earlier 2e-7 interpolation screen; normalizer accuracy is not cleared.','', 'Searching stock budget is 128 paths; checking is 256. VIX uses eight scrambles of 16/32 outer points respectively. Normalizer, conditional/time quadrature, stock discretization, rare tails and adaptive parameter selection remain separate sources of uncertainty. Sampling bands exclude deterministic errors. Physical-measure compatibility has not been re-established for the selected readout.','',f"Both starts were bounded to 35 evaluations, within the declared 30-minute optimization budget. Total run wall time: {r['wall_seconds']:.2f} seconds. Optimizer outcomes and every candidate remain in the run directory. This is a bounded attempt, not proof of global model feasibility or infeasibility.",'', '## Artifacts','',f'- Run: [{run.name}](runs/{run.name}/run.json).',f'- Replay audit: [score_audit.json](runs/{run.name}/score_audit.json).',f'- Search plan: [FULL_READOUT_FIT_PLAN.md](FULL_READOUT_FIT_PLAN.md).',f'- [Plots and reading guide](visualizations/{plots.name}/README.md).','']
 (HERE/'FULL_READOUT_FIT_RESULTS.md').write_text('\n'.join(lines))
 plots.mkdir(parents=True,exist_ok=True)
 guide=['# Eleven-parameter calibration pictures','', 'All seven agreed SPX maturities and all four VIX maturities have model overlays. Every market observation is in sample. Orange: old zero-shift reference repriced with the new estimator. Blue: selected eleven-parameter fit. Black/gray: market midpoint/bid–ask. Both model curves use the same observed market forwards for Black-IV conversion.','', '- [SPX smiles](spx-all-maturity-fit.png): seven expiries, OTM quotes, cutoff 3.', '- [VIX smiles](vix-all-maturity-fit.png): four expiries, OTM quotes.', '- [VIX forwards and variance input](forwards-and-variance.png).', '- [All eleven parameters and bounds](parameters.png).', '- [SPX price errors](spx-price-errors.png).', '- [VIX price errors](vix-price-errors.png).','', 'SVG copies support zooming. Shaded bands are ±2 sampling SE only; lower/upper IV endpoints may be unavailable. Raw prices and errors are retained in the run. Zero-payoff model estimates are shown as unavailable IVs, rather than a zero-volatility tail; they indicate finite-sample tail undercoverage and do not establish a true zero option value. No smoothing, clipping, strike-dependent controls or own-model-forward IV transformation is applied. Raw positive weighted payoff prices are monotone within each option side; this property does not establish overall pricing accuracy.','',conclusion,'', 'The report [FULL_READOUT_FIT_RESULTS.md](../../FULL_READOUT_FIT_RESULTS.md) contains scores, boundary choices and numerical limits. Searching and checking simulations differ, but the same market quotes enter both. Neither constitutes market out-of-sample performance.']
 (plots/'README.md').write_text('\n'.join(guide)+'\n')
if __name__=='__main__':
 p=argparse.ArgumentParser();p.add_argument('--run',type=Path,required=True);p.add_argument('--plots',type=Path,required=True);a=p.parse_args();summarize(a.run,a.plots)
